import{_ as e,o as t,c as a}from"./chunks/framework.CZqXuAiL.js";const u=JSON.parse(`{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"PingLess Studios","text":"Open-source infrastructure & security","tagline":"High-performance tools for servers, networks, and applications","image":{"src":"/pingles.png","alt":"PingLess Studios"},"actions":[{"theme":"brand","text":"Explore Projects","link":"/projects/"},{"theme":"alt","text":"Contact Us","link":"https://studio.pingless.org"},{"theme":"alt","text":"GitHub","link":"https://github.com/AnAverageBeing"}]},"features":[{"title":"🔒 OpenShield-XDP","details":"XDP-native DDoS mitigation at line rate. 16-stage pipeline, 42 attack vectors, Bloom filter acceleration, freplace hot-patching, 10 protection profiles with zero-tune presets.","link":"/openshield-xdp/"},{"title":"🔀 RouteX Reverse Proxy","details":"Production-grade L3/L4/L7 reverse proxy. Game protocol detection (MC Java/Bedrock/FiveM/GMod), behavioral scoring, bandwidth quotas, 36 REST API endpoints.","link":"/routex/"},{"title":"📊 Bandwidth Manager","details":"Per-container Docker bandwidth management. Speed limits, daily quotas, kernel-level tc enforcement, modern TUI, webhook alerts, zero external dependencies.","link":"/bandwidth-manager/"},{"title":"💾 S3 Database Storage for VPS","details":"Automatic PostgreSQL and MySQL/MariaDB backups to any S3-compatible storage. Interactive setup, systemd scheduling, retention, off-site + local copies, Discord alerts, extractor.","link":"/s3-database-storage-for-vps/"},{"title":"⚡ Penetration-v3","details":"Advanced traffic generation and packet crafting tool for authorized penetration testing. 38 methods, IPv6 raw sockets, HTTP/2 Rapid Reset, amplification scanning, and auto proxy rotation.","link":"/pentest-v3/"},{"title":"🛡️ Protection Plus","details":"Host-level abuse protection and antivirus for hosting providers. Miners, outbound DDoS, Tor exits, port scans, webshells, zip bombs and exploits — detected, attributed to the exact container or Pterodactyl server, and shut down automatically. One static binary.","link":"/protection/"},{"title":"🎮 Bandwidth Monitor for Pterodactyl","details":"Per-server network monitoring and bandwidth control for Pterodactyl panels. RX/TX speed caps, day/week/month quotas, throttle or suspend on exceed, pairing-token node agents, dashboards, reports and predictions in the admin UI.","link":"/pterodactyl-bandwidth-monitor/"},{"title":"Glacier Theme for Pterodactyl","details":"A calm, Apple-grade sidebar theme for Pterodactyl Panel. Dark and light palettes, glass, 16 background patterns, console zones editor, dashboard cards, tab manager and Ctrl+K search — zero core-file replacement.","link":"/glacier/"},{"title":"Apple Theme for Pterodactyl Admin","details":"An iOS-grade matte glass admin theme for Pterodactyl Panel. Catppuccin Latte and Mocha with 12 accents, a runtime-harvested sidebar that adapts to every extension, bento dashboard, branded boot loader — zero core-file replacement.","link":"/apple/"},{"title":"🛡️ LiteShield-XDP","details":"Free, minimal XDP (eBPF) firewall for Linux 5.15+. One XDP program, one Go binary, one YAML config — per-IP rate limiting, auto-ban, live TUI, Discord alerts.","link":"/liteshield-xdp/"},{"title":"🚀 NitroCord","details":"Velocity-compatible Minecraft proxy with built-in attack prevention. Kernel ipset firewall, TCP fingerprinting, anti-bot verification, anti-VPN/GeoIP, attack-mode adaptation — drop-in plugin compatible.","link":"/nitrocord/"},{"title":"Firewall-Plus for Pterodactyl","details":"Production-grade per-container iptables firewall for Pterodactyl Panel (Blueprint or standalone addon) plus a Wings node daemon, with DDoS SMART detection and automatic mitigation.","link":"/firewall-plus/"},{"title":"Panel Firewall for Pterodactyl","details":"Host-level DDoS protection for the Pterodactyl Panel host itself — L3/L4 iptables presets, EWMA auto-mitigation, and L7 access-log HTTP-flood bans via an HMAC-authenticated daemon with transactional rollback.","link":"/panel-firewall/"},{"title":"Glacier Pack for Pterodactyl","details":"24 standalone addons for Pterodactyl Panel plus the Glacier Pack hub — one custom dashboard hosting every addon's complete admin UI. Recycle bin, URL downloads, Minecraft installers, backups, subdomains, staff roles and more, all Glacier-native.","link":"/glacier-pack/"},{"title":"Pterodactyl Revamp","details":"Enterprise operations layer for Pterodactyl Panel — bulk server operations, multi-server creation, tagging, server templates, an allocation port picker, metrics and analytics, node/server health scoring, global search, and a full audit log.","link":"/pterodactyl-revamp/"},{"title":"Sentinel for Pterodactyl","details":"Fleet-wide security monitoring and enforcement for Pterodactyl — a Laravel panel addon (the brain) plus a static Go agent on each Wings node (the sensor/enforcer), with 12 detectors, graduated enforcement and central threat intel.","link":"/pterodactyl-sentinel/"},{"title":"Ask Access for Pterodactyl","details":"Server access requests for Pterodactyl Panel — users ask for access by server ID or owner email, owners approve with permission presets and optional time limits, with blocking, delegated managers, and a full audit trail.","link":"/ask-access/"},{"title":"Trash Bin Pro for Pterodactyl","details":"Recoverable file deletion for Pterodactyl Panel. Soft-delete trash bin with per-server quotas, per-egg retention windows, collision-safe restores, subuser permissions and a full admin panel.","link":"/trash-bin-pro/"},{"title":"Blue Mod Installer for Pterodactyl","details":"One-click Minecraft mod installer in the server sidebar — search Modrinth and CurseForge with loader/version filters and version browser, installed straight into /mods via Wings.","link":"/blue-mod-installer/"},{"title":"Blue Plugin Installer for Pterodactyl","details":"One-click Minecraft plugin installer in the server sidebar — browse Modrinth, CurseForge, Hangar, SpigotMC, and Polymart, with panel-side download and Wings upload into /plugins.","link":"/blue-plugin-installer/"},{"title":"Blue Server Properties Editor","details":"Modern categorized server.properties editor for Minecraft servers — toggles, dropdowns and 3-column grid with live Wings read/write, customizable sidebar label, Blueprint or Blueprint-free install.","link":"/blue-server-properties/"},{"title":"📡 More Coming Soon","details":"PingLess Studios is actively developing new infrastructure and security tools. Follow on GitHub for updates.","link":"https://github.com/AnAverageBeing"}],"footer":{"message":"© 2025-2026 PingLess Studios — <a href='https://studio.pingless.org'>studio.pingless.org</a>"}},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":null}`),i={name:"index.md"};function r(o,n,l,s,d,c){return t(),a("div")}const g=e(i,[["render",r]]);export{u as __pageData,g as default};
